@patch
def __ft__(self: CrossingPlan):
    status = '✅' if self.feasible else '❌'
    corridor = self.corridor
    color = _style_color(corridor.style, '#2c3e50')

    # ── 1. Header: status + route + schematic ──
    header = Div(
        _color_dot(color, 14),
        Span(f' Crossing Plan {status}', cls='uk-text-bold'),
        Span(f' ⬡{corridor.start} → ⬡{corridor.end}', cls='uk-text-muted'),
        Span(f' t{self.queen_start_turn}→t{self.queen_arrival}',
             cls='uk-text-muted uk-margin-small-left'),
    )
    schematic = _corridor_schematic(corridor)
    stats = Small(
        f'food margin {self.food_margin:.1f}'
        + (f' · bishop fuel {self.bishop_fuel_used:.0f}' if self.bishop_fuel_used else ''),
        cls='uk-text-muted',
    )

    # ── 2. Roster: piece icons grouped by role ──
    needed = self.pieces_needed()
    role_icons = {
        PieceType.QUEEN:  '♛', PieceType.BISHOP: '♝',
        PieceType.KNIGHT: '♞', PieceType.ROOK:   '♜',
        PieceType.PAWN:   '♟', PieceType.KING:   '♚',
    }
    role_labels = []
    for pt, count in needed.items():
        icon = role_icons.get(pt, '?')
        role_labels.append(
            Span(f'{icon}×{count}', style='font-size:1.3em;margin-right:0.8em'))
    # Add the queen (not in pieces_needed since it filters role != queen)
    queen_span = Span('♛', style='font-size:1.3em;margin-right:0.8em',
                       title='Queen')
    roster_row = Div(
        queen_span, *role_labels,
        style='display:flex;align-items:center;gap:0.2em;padding:0.3em 0',
    )

    # ── 3. Segment cards ──
    if corridor.segments:
        seg_grid = Div(*[s.__ft__() for s in corridor.segments],
                       cls='uk-flex uk-flex-row uk-flex-wrap',
                       style='gap:0.5rem')
    else:
        seg_grid = P(Em('No segments'), cls='uk-text-muted')

    return Div(
        Card(header, schematic, stats, cls='uk-card-small'),
        Card(roster_row, cls='uk-card-small'),
        seg_grid,
    )

